+package main
+
+import (
+	"context"
+	"encoding/json"
+	"errors"
+	"io"
+	"net/http"
+	"os"
+	"path/filepath"
+	"strings"
+	"sync/atomic"
+	"time"
+
+	"github.com/egoist/mygo"
+	"github.com/egoist/mygo/ui"
+	"ytmgo/internal/catalog"
+	"ytmgo/internal/language"
+)
+
+// This entry point is an isolated native-interaction fixture, not a service,
+// account, captcha, or playback success test. No account/player lifecycle runs.
+type auditTransport struct {
+	requests atomic.Int64
+	status   atomic.Int64
+}
+
+func (t *auditTransport) RoundTrip(req *http.Request) (*http.Response, error) {
+	if req.Method != http.MethodPost || req.URL.Scheme != "https" || req.URL.Host != "music.youtube.com" || req.URL.Path != "/youtubei/v1/browse" {
+		return nil, errors.New("audit_request_outside_fixture")
+	}
+	n := t.requests.Add(1)
+	status, body := http.StatusOK, `{"contents":{}}`
+	header := make(http.Header)
+	header.Set("Content-Type", "application/json")
+	if n == 1 {
+		status, body = http.StatusFound, ""
+		header.Set("Location", "https://www.google.com/sorry/")
+	}
+	t.status.Store(int64(status))
+	return &http.Response{StatusCode: status, Header: header, Body: io.NopCloser(strings.NewReader(body)), Request: req}, nil
+}
+
+type auditSnapshot struct {
+	Schema              int           `json:"schema"`
+	Fixture             string        `json:"fixture"`
+	Scenario            string        `json:"scenario"`
+	Requests            int64         `json:"requests"`
+	LatestHTTPStatus    int64         `json:"latest_http_status"`
+	ErrorActive         bool          `json:"error_active"`
+	RecoveryKind        recoveryKind  `json:"recovery_kind"`
+	RecoveryScope       recoveryScope `json:"recovery_scope"`
+	Loading             bool          `json:"loading"`
+	DialogOpen          bool          `json:"dialog_open"`
+	BrowserLaunchFailed bool          `json:"browser_launch_failed"`
+	SignedInUI          bool          `json:"signed_in_ui"`
+	PremiumUI           bool          `json:"premium_ui"`
+	RealAccountUsed     bool          `json:"real_account_used"`
+}
+
+func main() {
+	const name = "ytmgo Recovery AUDIT"
+	mygo.App.SetName(name)
+	if !mygo.App.RequestSingleInstanceLock() {
+		return
+	}
+	ctx, cancel := context.WithCancel(context.Background())
+	a := &desktop{ctx: ctx, cancel: cancel, queueIndex: -1, historyIndex: -1}
+	a.model = UIModel{Route: "home", Appearance: "dark", Language: "en", PanelTab: "queue"}
+	mygo.App.SetLanguages(language.Supported...)
+	mygo.App.SetLocale("en")
+	mygo.Theme.SetSource(mygo.ThemeDark)
+	transport := &auditTransport{}
+	a.catalog = catalog.NewWithOptions(catalog.Options{HTTPClient: &http.Client{Transport: transport}, Language: "en"})
+	exe, err := os.Executable()
+	if err != nil {
+		return
+	}
+	evidence := filepath.Clean(filepath.Join(filepath.Dir(exe), "..", "..", "..", "audit-state.json"))
+	scenario := "anonymous"
+	var last auditSnapshot
+	observe := func() {
+		s := auditSnapshot{Schema: 1, Fixture: "synthetic_catalog_302_then_200", Scenario: scenario,
+			Requests: transport.requests.Load(), LatestHTTPStatus: transport.status.Load(),
+			ErrorActive: a.model.Error != "", RecoveryKind: a.model.ErrorRecovery.Kind,
+			RecoveryScope: a.model.ErrorRecovery.Scope, Loading: a.model.Loading,
+			DialogOpen: a.model.RecoveryOpen, BrowserLaunchFailed: a.model.RecoveryBrowserFailed,
+			SignedInUI: a.model.SignedIn, PremiumUI: a.model.MusicPremium}
+		if s == last {
+			return
+		}
+		last = s
+		if data, err := json.MarshalIndent(s, "", "  "); err == nil {
+			if os.WriteFile(evidence+".tmp", append(data, '\n'), 0600) == nil {
+				_ = os.Rename(evidence+".tmp", evidence)
+			}
+		}
+	}
+	reset := func(identity string) {
+		if a.model.Loading {
+			return
+		}
+		if a.pageCancel != nil {
+			a.pageCancel()
+		}
+		a.pageGeneration++
+		// New transport/client isolates counters even if an old request finishes.
+		transport = &auditTransport{}
+		a.catalog = catalog.NewWithOptions(catalog.Options{HTTPClient: &http.Client{Transport: transport}, Language: language.ServiceLanguage(mygo.App.Locale())})
+		scenario = identity
+		a.model.SignedIn, a.model.MusicPremium = identity != "anonymous", identity == "premium"
+		a.model.RecoveryOpen, a.model.RecoveryBrowserFailed = false, false
+		a.model.Recovery = recoveryNotice{}
+		a.history, a.historyIndex = nil, -1
+		a.window.SetTitle(name + " — " + identity + " — SYNTHETIC; NO ACCOUNT / CAPTCHA TEST")
+		a.navigate("home")
+	}
+	noop := func() {}
+	noItem := func(catalog.Item) {}
+	accountDisabled := func() {
+		a.window.SetTitle(name + " — account operations disabled; use AUDIT menu")
+	}
+	// Native recovery help/browser/retry bindings are the production callbacks.
+	// All account/player entry points are deliberately absent from this fixture.
+	actions := ViewActions{Tr: a.tr, TrArgs: a.trArgs, Navigate: a.navigate, Search: func(string) {},
+		Open: noItem, Play: noItem, QueueAppend: noItem, PlayQueue: func(int) {}, LoadMore: noop,
+		Toggle: noop, Next: noop, Previous: noop, Like: noop, Shuffle: noop, Repeat: noop, Mute: noop,
+		Back: noop, Forward: noop, Reload: a.reload, Account: accountDisabled, SignOut: accountDisabled,
+		Seek: func(float64) {}, Volume: func(float64) {}, Video: func(bool) {}, RetryPlayback: noop,
+		Appearance:   func(value string) { a.model.Appearance = value; a.invalidate() },
+		Language:     func(value string) { a.model.Language = value; mygo.App.SetLocale(value); a.invalidate() },
+		ShowRecovery: a.showRecovery, OpenRecoveryBrowser: a.openRecoveryBrowser, RetryRecovery: a.retryRecovery}
+	mygo.App.SetMenu(mygo.NewMenu([]*mygo.MenuItem{
+		{Role: mygo.RoleAppMenu},
+		{Label: "AUDIT — synthetic state", Submenu: []*mygo.MenuItem{
+			menuItem("Anonymous fixture (reset 302)", "CmdOrCtrl+1", func() { reset("anonymous") }),
+			menuItem("Standard fixture (reset 302)", "CmdOrCtrl+2", func() { reset("standard") }),
+			menuItem("Premium fixture (reset 302)", "CmdOrCtrl+3", func() { reset("premium") }),
+			mygo.Separator(),
+			menuItem("Compact 420 × 740", "CmdOrCtrl+4", func() { a.window.SetSize(420, 740) }),
+			menuItem("Wide 1100 × 840", "CmdOrCtrl+5", func() { a.window.SetSize(1100, 840) }),
+		}},
+		{Role: mygo.RoleEditMenu}, {Role: mygo.RoleWindowMenu},
+	}))
+	mygo.App.OnBeforeQuit(func(*mygo.QuitEvent) { cancel() })
+	mygo.App.OnWindowAllClosed(func() { mygo.App.Quit() })
+	mygo.App.OnActivate(func(bool) { a.show() })
+	mygo.App.WhenReady(func() {
+		a.window = mygo.NewWindow(mygo.WindowOptions{Title: name, Width: 1100, Height: 840, MinWidth: 380, MinHeight: 640,
+			Content: ui.View(func(c *ui.Context) { nativeView(c, &a.model, actions); observe() })})
+		a.windowVisible = true
+		reset("anonymous")
+		go func() {
+			ticker := time.NewTicker(200 * time.Millisecond)
+			defer ticker.Stop()
+			for {
+				select {
+				case <-ctx.Done():
+					return
+				case <-ticker.C:
+					a.post(observe)
+				}
+			}
+		}()
+	})
+	_ = mygo.App.Run()
+}
