+package main
+
+import (
+	"context"
+	"errors"
+	"net/http"
+	"testing"
+
+	"ytmgo/internal/catalog"
+)
+
+func TestAuditSyntheticCatalogContract(t *testing.T) {
+	transport := &auditTransport{}
+	client := catalog.NewWithOptions(catalog.Options{HTTPClient: &http.Client{Transport: transport}})
+	_, err := client.Home(context.Background())
+	var failure *catalog.HTTPError
+	if !errors.As(err, &failure) || failure.StatusCode != 302 || failure.Redirect != "google_challenge" || transport.requests.Load() != 1 {
+		t.Fatal("audit first request did not exercise production redirect classification exactly once")
+	}
+	notice := catalogRecovery(err, recoveryCatalog)
+	if notice != (recoveryNotice{Kind: recoveryChallenge, Scope: recoveryCatalog}) {
+		t.Fatal("audit failure did not reach production recovery classification")
+	}
+	if _, err := client.Home(context.Background()); err != nil || transport.requests.Load() != 2 || transport.status.Load() != 200 {
+		t.Fatal("audit second request did not parse production catalog success")
+	}
+}
